  function realLocate(rooms, p) {
    const b = REAL_BUILDINGS.find((b2) => p.x >= b2.x0 && p.x <= b2.x1 && p.z >= b2.z0 && p.z <= b2.z1);
    if (!b) return "";
    if (b.outdoor) return b.name;
    const floor = Math.max(1, Math.min(5, FB.findLastIndex((y) => p.y >= y - 0.6) + 1));
    const r = rooms.find((r2) => r2.building === b.name && r2.floor === floor && p.x >= r2.x0 - 0.2 && p.x <= r2.x1 + 0.2 && p.z >= r2.z0 - 0.2 && p.z <= r2.z1 + 0.2);
    return b.name + " " + floor + "F" + (r ? " \xB7 " + r.name + (r.cls ? " " + r.cls : "") : "");
  }

