    inspect: [[0, {}], [0.25, { x: -0.08, y: 0.04, ry: 0.9, rz: 0.5 }], [0.4, { x: -0.08, y: 0.04, ry: 0.9, rz: 0.5 }], [0.6, { x: -0.04, y: 0.02, ry: -0.2, rz: 0.25, rx: 0.3 }], [0.8, { x: -0.04, y: 0.02, ry: -0.2, rz: 0.25, rx: 0.3 }], [1, {}]]
